ARTIFACT_NAMESPACE = "lkr_view_sync"

lookml_group = typer.Typer(
    name="lookml",
    help="LookML synchronization and deployment tools",
    no_args_is_help=True,
)

VALID_EXTENSIONS = (
    ".lkml",
    ".lookml",
    ".json",
    ".geojson",
    ".md",
    ".gitkeep",
)


def _get_file_id(f: Any) -> str:
    if isinstance(f, dict):
        return str(f.get("id") or f.get("path") or str(f))
    if hasattr(f, "id") and f.id is not None:
        return str(f.id)
    if hasattr(f, "path") and f.path is not None:
        return str(f.path)
    return str(f)


def _resolve_project_id(
    folder_name: str | None, project_id_opt: str | None
) -> str:
    if project_id_opt:
        return project_id_opt
    if folder_name:
        return os.path.basename(os.path.abspath(folder_name.rstrip("/\\")))
    env_proj = os.getenv("LOOKER_PROJECT_NAME")
    if env_proj:
        return env_proj
    return os.path.basename(os.getcwd())


def _ensure_remote_directory(
    sdk: ExtendedLooker40SDK, project_id: str, file_path: str
) -> None:
    dir_path = os.path.dirname(file_path.replace("\\", "/"))
    if not dir_path or dir_path == "." or dir_path == "/":
        return

    parts = [p for p in dir_path.split("/") if p]
    current_path = ""
    for part in parts:
        current_path = f"{current_path}/{part}" if current_path else part
        try:
            sdk.create_project_directory(
                project_id=project_id,
                directory_path=current_path,
            )
        except Exception as e:  # noqa: BLE001
            logger.debug(f"Directory creation notice for '{current_path}': {e}")


def _ensure_model_configuration(
    sdk: ExtendedLooker40SDK, project_id: str, files_to_push: list[dict[str, str]]
) -> None:
    model_files = [
        f for f in files_to_push if f["root_name"].endswith(".model.lkml")
    ]
    if not model_files:
        return

    try:
        raw_models = sdk.all_lookml_models() or []
        existing_models: dict[str, Any] = {
            str(m.get("name") if isinstance(m, dict) else getattr(m, "name", "")): m
            for m in raw_models
            if (m.get("name") if isinstance(m, dict) else getattr(m, "name", None))
        }
    except Exception as e:  # noqa: BLE001
        logger.debug(f"Could not fetch existing LookML models: {e}")
        existing_models = {}

    for mf in model_files:
        root_name = mf["root_name"]
        content = mf["content"]
        model_name = root_name[: -len(".model.lkml")]

        match = re.search(
            r'^\s*connection:\s*["\']?([^"\'\s;#]+)["\']?', content, re.MULTILINE
        )
        conn_name = match.group(1).strip() if match else None

        existing = existing_models.get(model_name)
        if not existing:
            logger.info(f"Creating LookML model configuration for '{model_name}'...")
            allowed_conns = [conn_name] if conn_name else []
            body = models40.WriteLookmlModel(
                name=model_name,
                project_name=project_id,
                allowed_db_connection_names=allowed_conns,
            )
            try:
                sdk.create_lookml_model(body=body)
            except Exception as e:  # noqa: BLE001
                logger.debug(f"Notice creating LookML model '{model_name}': {e}")
        else:
            existing_proj = (
                existing.get("project_name")
                if isinstance(existing, dict)
                else getattr(existing, "project_name", None)
            )
            raw_allowed = (
                existing.get("allowed_db_connection_names")
                if isinstance(existing, dict)
                else getattr(existing, "allowed_db_connection_names", None)
            ) or []
            allowed_conns = [str(c) for c in raw_allowed]

            needs_update = False
            if existing_proj and existing_proj != project_id:
                needs_update = True
            if conn_name and conn_name not in allowed_conns:
                allowed_conns.append(conn_name)
                needs_update = True

            if needs_update:
                logger.info(
                    f"Updating LookML model configuration for '{model_name}'..."
                )
                body = models40.WriteLookmlModel(
                    name=model_name,
                    project_name=project_id,
                    allowed_db_connection_names=allowed_conns,
                )
                try:
                    sdk.update_lookml_model(
                        lookml_model_name=model_name, body=body
                    )
                except Exception as e:  # noqa: BLE001
                    logger.debug(f"Notice updating LookML model '{model_name}': {e}")


@lookml_group.command(name="push")
def push(
    ctx: typer.Context,
    folder_name: Annotated[
        str, typer.Argument(help="Local folder name / Looker project ID to push")
    ],
    project_id_opt: Annotated[
        str | None,
        typer.Option(
            "--project-id",
            "--project",
            help="Looker project ID to push to (if different from folder name)",
        ),
    ] = None,
    file_opt: Annotated[
        str | None,
        typer.Option(
            "--file",
            "-f",
            help="Single file relative path (or absolute path) to push",
        ),
    ] = None,
    deploy: Annotated[
        bool,
        typer.Option("--deploy", help="Commit and deploy to production after push"),
    ] = False,
    reset: Annotated[
        bool,
        typer.Option(
            "--reset/--no-reset",
            help="Reset developer workspace to production before pushing",
        ),
    ] = True,
    message: Annotated[
        str, typer.Option("--message", help="Commit message when deploying")
    ] = "push from lkr cli",
):
    """
    Push local files to Looker, removing files on the instance that aren't being pushed.
    If --file / -f is specified (or folder_name is a file), only that single file is pushed without deleting remote orphans.
    """
    auth = get_auth(ctx)
    sdk: ExtendedLooker40SDK = auth.get_current_sdk()

    if file_opt is None and os.path.isfile(folder_name):
        file_opt = folder_name
        folder_name = os.path.dirname(os.path.abspath(folder_name))

    project_id = _resolve_project_id(folder_name, project_id_opt)
    lookml_dir = os.path.abspath(folder_name)

    try:
        sdk.update_session(models40.WriteApiSession(workspace_id="dev"))
    except Exception as sess_err:  # noqa: BLE001
        logger.debug(f"Session switch notice: {sess_err}")

    if reset:
        logger.info(
            f"Resetting developer workspace to production for project {project_id}..."
        )
        try:
            sdk.reset_project_to_production(project_id=project_id)
        except Exception as reset_err:  # noqa: BLE001
            logger.debug(
                f"Reset to production notice ({reset_err}), attempting developer_copy first..."
            )
            try:
                sdk.create_developer_copy(project_id=project_id)
                sdk.reset_project_to_production(project_id=project_id)
            except Exception as copy_err:  # noqa: BLE001
                logger.debug(f"Developer copy / reset notice: {copy_err}")


    files_to_push = []
    if file_opt:
        full_path = file_opt if os.path.isabs(file_opt) else os.path.join(lookml_dir, file_opt)
        full_path = os.path.abspath(full_path)
        try:
            if os.path.commonpath([lookml_dir, full_path]) != lookml_dir:
                logger.error(f"Path traversal detected and blocked: {file_opt}")
                raise typer.Exit(1)
        except ValueError:
            logger.error(f"Path traversal detected and blocked: {file_opt}")
            raise typer.Exit(1)

        if not os.path.exists(full_path):
            logger.error(f"Local file does not exist: {full_path}")
            raise typer.Exit(1)

        filename = os.path.basename(full_path)
        if not any(filename.endswith(ext) for ext in VALID_EXTENSIONS):
            logger.error(f"Local file '{filename}' has an extension not supported by Looker.")
            raise typer.Exit(1)

        rel_path = os.path.relpath(full_path, lookml_dir).replace("\\", "/")
        with open(full_path, "r", encoding="utf-8") as f:
            content = f.read()
        files_to_push.append({
            "path": rel_path,
            "root_name": filename,
            "content": content,
        })
    else:
        if not os.path.exists(lookml_dir):
            logger.error(f"Local folder does not exist: {lookml_dir}")
            raise typer.Exit(1)

        logger.info(f"Reading local files from {lookml_dir} for project {project_id}...")
        for root, _, files in os.walk(lookml_dir):
            if ".git" in root.split(os.sep):
                continue
            for file in files:
                if file in (".gitignore", ".DS_Store"):
                    continue
                if any(file.endswith(ext) for ext in VALID_EXTENSIONS):
                    full_path = os.path.join(root, file)
                    rel_path = os.path.relpath(full_path, lookml_dir).replace("\\", "/")
                    with open(full_path, "r", encoding="utf-8") as f:
                        content = f.read()
                    files_to_push.append({
                        "path": rel_path,
                        "root_name": file,
                        "content": content,
                    })
                else:
                    logger.warning(
                        f"Local file '{file}' has an extension not supported by Looker and will be skipped."
                    )

    successfully_pushed_paths = set()
    for f in files_to_push:
        structured_path = f["path"]
        root_path = f["root_name"]
        content = f["content"]

        try:
            logger.info(f"Uploading/Overwriting remote file: {structured_path}")
            file_content = FileContent(path=structured_path, content=content)
            try:
                sdk.update_file(
                    project_id=project_id,
                    file_content=file_content,
                )
            except Exception:  # noqa: BLE001
                try:
                    sdk.create_file(
                        project_id=project_id,
                        file_content=file_content,
                    )
                except Exception:  # noqa: BLE001
                    _ensure_remote_directory(
                        sdk=sdk, project_id=project_id, file_path=structured_path
                    )
                    sdk.create_file(
                        project_id=project_id,
                        file_content=file_content,
                    )
            successfully_pushed_paths.add(structured_path)
            continue
        except Exception as struct_err:  # noqa: BLE001
            logger.debug(
                f"Structured upload notice ({struct_err}), initiating fallback to project root..."
            )

        if root_path.endswith(".model.lkml"):
            content = re.sub(
                r'include:\s*["\']/views/\*\*/\*\.view\.lkml["\']',
                'include: "/*.view.lkml"',
                content,
            )

        root_file_content = FileContent(path=root_path, content=content)
        try:
            sdk.update_file(
                project_id=project_id,
                file_content=root_file_content,
            )
        except Exception:  # noqa: BLE001
            sdk.create_file(
                project_id=project_id,
                file_content=root_file_content,
            )
        successfully_pushed_paths.add(root_path)

    if not file_opt:
        logger.info("Retrieving remote file inventory to enforce one-way mirror...")
        existing_remote = sdk.all_project_files(project_id=project_id) or []
        for rf in existing_remote:
            rf_path = _get_file_id(rf)
            if not any(rf_path.endswith(ext) for ext in VALID_EXTENSIONS):
                logger.warning(
                    f"Remote file '{rf_path}' has an extension not supported by Looker."
                )
            if (
                rf_path not in successfully_pushed_paths
                and not rf_path.endswith(".gitkeep")
                and rf_path != "manifest.lkml"
            ):
                logger.info(f"Deleting remote orphan file: {rf_path}")
                try:
                    sdk.delete_file(project_id=project_id, file_path=rf_path)
                except Exception as dpe:  # noqa: BLE001
                    logger.debug(f"Deletion notice for {rf_path}: {dpe}")

    _ensure_model_configuration(
        sdk=sdk, project_id=project_id, files_to_push=files_to_push
    )

    logger.info("Push completed successfully.")

    if deploy:
        logger.info(f"Committing and deploying project {project_id} to production...")
        try:
            commit_req = ProjectCommitRequest(message=message).model_dump(
                exclude_none=True
            )
            sdk.commit(project_id=project_id, body=commit_req)
        except Exception as commit_err:  # noqa: BLE001
            logger.debug(f"Commit notice: {commit_err}")

        sdk.deploy_to_production(project_id=project_id)
        logger.info("Deployment completed successfully.")


@lookml_group.command(name="pull")
def pull(
    ctx: typer.Context,
    folder_name: Annotated[
        str, typer.Argument(help="Local folder name / Looker project ID to pull into")
    ],
    project_id_opt: Annotated[
        str | None,
        typer.Option(
            "--project-id",
            "--project",
            help="Looker project ID to pull from (if different from folder name)",
        ),
    ] = None,
    file_opt: Annotated[
        str | None,
        typer.Option(
            "--file",
            "-f",
            help="Single file relative path to pull from Looker",
        ),
    ] = None,
    deploy: Annotated[
        bool,
        typer.Option(
            "--deploy", help="Commit and deploy to production on Looker after pull"
        ),
    ] = False,
    message: Annotated[
        str, typer.Option("--message", help="Commit message when deploying")
    ] = "pull from lkr cli then commit and deploy",
):
    """
    Pull remote files from Looker to local disk, removing local files that aren't on the instance.
    If --file / -f is specified, only that single file is pulled without deleting local orphans.
    """
    auth = get_auth(ctx)
    sdk: ExtendedLooker40SDK = auth.get_current_sdk()
    project_id = _resolve_project_id(folder_name, project_id_opt)

    target_dir = os.path.abspath(folder_name)
    os.makedirs(target_dir, exist_ok=True)

    if file_opt:
        full_path = file_opt if os.path.isabs(file_opt) else os.path.join(target_dir, file_opt)
        resolved_local = os.path.abspath(full_path)
        try:
            if os.path.commonpath([target_dir, resolved_local]) != target_dir:
                logger.error(f"Path traversal detected and blocked: {file_opt}")
                raise typer.Exit(1)
        except ValueError:
            logger.error(f"Path traversal detected and blocked: {file_opt}")
            raise typer.Exit(1)

        rf_path = os.path.relpath(resolved_local, target_dir).replace("\\", "/")
        if not any(rf_path.endswith(ext) for ext in VALID_EXTENSIONS):
            logger.error(
                f"File '{rf_path}' has an extension not supported by Looker."
            )
            raise typer.Exit(1)

        try:
            content = sdk.get_file_content(project_id=project_id, file_path=rf_path)
        except Exception as e:  # noqa: BLE001
            logger.error(f"Failed to fetch content for remote file {rf_path}: {e}")
            raise typer.Exit(1)

        os.makedirs(os.path.dirname(resolved_local), exist_ok=True)
        with open(resolved_local, "w", encoding="utf-8") as f:
            f.write(content)
        logger.info(f"Pulled file: {rf_path}")
    else:
        logger.info(
            f"Retrieving remote files for project {project_id} to pull into {target_dir}..."
        )
        existing_remote = sdk.all_project_files(project_id=project_id) or []

        remote_paths = set()
        for rf in existing_remote:
            rf_path = _get_file_id(rf)
            if not any(rf_path.endswith(ext) for ext in VALID_EXTENSIONS):
                logger.warning(
                    f"Remote file '{rf_path}' has an extension not supported by Looker."
                )
                continue
            if rf_path.endswith(".gitkeep"):
                continue

            local_path = os.path.join(target_dir, rf_path)
            resolved_local = os.path.abspath(local_path)
            try:
                if os.path.commonpath([target_dir, resolved_local]) != target_dir:
                    logger.warning(f"Path traversal detected and blocked: {rf_path}")
                    continue
            except ValueError:
                logger.warning(f"Path traversal detected and blocked: {rf_path}")
                continue

            try:
                content = sdk.get_file_content(project_id=project_id, file_path=rf_path)
            except Exception as e:  # noqa: BLE001
                if "not found" in str(e).lower():
                    logger.debug(
                        f"Remote file {rf_path} not found in dev workspace (likely a deleted ghost file in git tracking)."
                    )
                else:
                    logger.error(f"Failed to fetch content for remote file {rf_path}: {e}")
                continue

            remote_paths.add(rf_path)

            os.makedirs(os.path.dirname(local_path), exist_ok=True)
            with open(local_path, "w", encoding="utf-8") as f:
                f.write(content)
            logger.info(f"Pulled file: {rf_path}")

        logger.info("Cleaning up local orphans not present on the Looker instance...")
        for root, _, files in os.walk(target_dir):
            if ".git" in root.split(os.sep):
                continue
            for file in files:
                if file in (".gitignore", ".DS_Store"):
                    continue
                if any(file.endswith(ext) for ext in VALID_EXTENSIONS):
                    full_path = os.path.join(root, file)
                    rel_path = os.path.relpath(full_path, target_dir).replace("\\", "/")
                    if (
                        rel_path not in remote_paths
                        and not rel_path.endswith(".gitkeep")
                        and rel_path != "manifest.lkml"
                    ):
                        logger.info(f"Deleting local orphan file: {rel_path}")
                        try:
                            os.remove(full_path)
                        except Exception as err:  # noqa: BLE001
                            logger.debug(f"Local deletion notice for {rel_path}: {err}")
                else:
                    logger.warning(
                        f"Local file '{file}' has an extension not supported by Looker and will not be synchronized or deleted."
                    )

    logger.info("Pull completed successfully.")

    if deploy:
        logger.info(
            f"Committing and deploying project {project_id} to production on Looker..."
        )
        try:
            commit_req = ProjectCommitRequest(message=message).model_dump(
                exclude_none=True
            )
            sdk.commit(project_id=project_id, body=commit_req)
        except Exception as commit_err:  # noqa: BLE001
            logger.debug(f"Commit notice: {commit_err}")

        sdk.deploy_to_production(project_id=project_id)
        logger.info("Deployment completed successfully.")


@lookml_group.command(name="deploy")
def deploy_cmd(
    ctx: typer.Context,
    folder_name: Annotated[
        str | None,
        typer.Argument(help="Local folder name / Looker project ID to deploy"),
    ] = None,
    project_id: Annotated[
        str | None,
        typer.Option(
            "--project-id",
            "--project",
            help="Looker project ID to deploy (if folder_name not specified)",
        ),
    ] = None,
    message: Annotated[
        str, typer.Option("--message", help="Commit message")
    ] = "commit and deploy from lkr cli",
):
    """
    Commit dev workspace and deploy Looker project to production.
    """
    auth = get_auth(ctx)
    sdk: ExtendedLooker40SDK = auth.get_current_sdk()
    resolved_project_id = _resolve_project_id(folder_name, project_id)

    logger.info(
        f"Committing and deploying project {resolved_project_id} to production..."
    )
    try:
        commit_req = ProjectCommitRequest(message=message).model_dump(
            exclude_none=True
        )
        sdk.commit(
            project_id=resolved_project_id,
            body=commit_req,
        )
    except Exception as commit_err:  # noqa: BLE001
        logger.debug(f"Commit notice: {commit_err}")

    sdk.deploy_to_production(project_id=resolved_project_id)
    logger.info("Deployment completed successfully.")


def _attr(obj: Any, key: str, default: Any = "") -> Any:
    return (obj.get(key) if isinstance(obj, dict) else getattr(obj, key, None)) or default


def is_autogenerated_view(content: str) -> bool:
    """Return True if the LookML view starts with the # AUTOGENERATED header."""
    return content.lstrip().startswith("# AUTOGENERATED")


def _log_sync_artifact(sdk: ExtendedLooker40SDK, entry: dict[str, Any]) -> None:
    try:
        key = re.sub(r"[^a-zA-Z0-9._-]", "_", str(entry.get("event_id", "sync")))
        sdk.update_artifacts(
            namespace=ARTIFACT_NAMESPACE,
            body=[
                models40.UpdateArtifact(
                    key=key, value=json.dumps(entry), content_type="application/json"
                )
            ],
        )
    except Exception as e:  # noqa: BLE001
        logger.debug(f"Artifact logging notice: {e}")


def _open_github_pr(
    sdk: ExtendedLooker40SDK, project_id: str, branch_name: str, title: str
) -> str | None:
    token = os.getenv("GITHUB_TOKEN") or os.getenv("GH_TOKEN")
    if not token:
        return None
    try:
        proj = sdk.project(project_id=project_id)
        remote_url = str(_attr(proj, "git_remote_url", ""))
        base_branch = str(_attr(proj, "git_production_branch_name", "main"))
        m = re.search(r"github\.com[:/]([^/]+/[^/.]+?)(?:\.git)?$", remote_url)
        if not m:
            return None
        resp = requests.post(
            f"https://api.github.com/repos/{m.group(1)}/pulls",
            headers={
                "Authorization": f"Bearer {token}",
                "Accept": "application/vnd.github+json",
            },
            json={
                "title": title,
                "head": branch_name,
                "base": base_branch,
                "body": f"Automated LookML view sync from `lkr tools lookml create` ({title}).",
            },
            timeout=15,
        )
        return resp.json().get("html_url") if resp.ok else None
    except Exception as e:  # noqa: BLE001
        logger.debug(f"GitHub PR fallback notice: {e}")
        return None


def _parse_event_json(raw_event: str) -> tuple[str | None, str | None, str | None, str]:
    data = json.loads(raw_event)
    proto = data.get("protoPayload") or data
    method = str(proto.get("methodName") or data.get("event_type") or "manual")
    res_name = str(proto.get("resourceName") or data.get("resourceName") or "")
    m = re.search(r"projects/([^/]+)/datasets/([^/]+)/tables/([^/]+)", res_name)
    if m:
        return m.group(1), m.group(2), m.group(3), method
    return data.get("dataset"), data.get("schema"), data.get("table"), method


def _resolve_matching_tables(
    sdk: ExtendedLooker40SDK,
    connection: str,
    dataset: str | None,
    schema: str | None,
    table: str | None,
    match_pattern: str | None,
) -> list[tuple[str | None, str, str]]:
    if (
        table
        and not match_pattern
        and not any(c in table for c in "*?[")
        and (not schema or not any(c in schema for c in "*?["))
    ):
        return [(dataset, schema or "", table)]

    if match_pattern:
        parts = match_pattern.split(".")
        if len(parts) >= 3:
            ds_pat, schema_pat, table_pat = parts[0], parts[1], ".".join(parts[2:])
            if not dataset and not any(c in ds_pat for c in "*?["):
                dataset = ds_pat
        elif len(parts) == 2:
            schema_pat, table_pat = parts[0], parts[1]
        else:
            schema_pat, table_pat = schema or "*", parts[0]
    else:
        schema_pat, table_pat = schema or "*", table or "*"

    if schema and not any(c in schema for c in "*?[") and schema_pat in ("*", schema):
        schema_names = [schema]
    else:
        schema_names = [
            s_name
            for s in (sdk.connection_schemas(connection) or [])
            if (s_name := str(_attr(s, "name")))
            and fnmatch.fnmatchcase(s_name, schema_pat)
            and (not schema or fnmatch.fnmatchcase(s_name, schema))
        ]

    matched: list[tuple[str | None, str, str]] = []
    for s_name in schema_names:
        for st in sdk.connection_tables(connection, schema_name=s_name) or []:
            items = _attr(st, "tables", None)
            for t in items if items is not None else [st]:
                t_name = str(_attr(t, "name"))
                if (
                    t_name
                    and fnmatch.fnmatchcase(t_name, table_pat)
                    and (not table or fnmatch.fnmatchcase(t_name, table))
                ):
                    matched.append((dataset, s_name, t_name))
    return matched


def create_lookml_views(
    sdk: ExtendedLooker40SDK,
    project_id: str,
    connection: str,
    model_name: str | None = None,
    dataset: str | None = None,
    schema: str | None = None,
    table: str | None = None,
    match: str | None = None,
    folder: str | None = None,
    branch_prefix: str = "lkr-sync/",
    deploy: bool = True,
    create_pr: bool = False,
    event_json: str | None = None,
) -> dict[str, Any]:
    """Create or update LookML views from any Looker database connection via the Looker API."""
    event_type = "manual"
    if event_json:
        ev_ds, ev_sch, ev_tbl, event_type = _parse_event_json(event_json)
        dataset, schema, table = dataset or ev_ds, schema or ev_sch, table or ev_tbl

    resolved_model = model_name or project_id

    try:
        sdk.update_session(models40.WriteApiSession(workspace_id="dev"))
    except Exception as e:  # noqa: BLE001
        logger.debug(f"Session switch notice: {e}")

    try:
        sdk.reset_project_to_production(project_id=project_id)
    except Exception:  # noqa: BLE001
        try:
            sdk.create_developer_copy(project_id=project_id)
            sdk.reset_project_to_production(project_id=project_id)
        except Exception as e:  # noqa: BLE001
            logger.debug(f"Developer copy / reset notice: {e}")

    now_dt = datetime.now(UTC)
    now_iso = now_dt.isoformat()
    branch_name = f"{branch_prefix.rstrip('/')}/{now_dt.strftime('%Y%m%d%H%M%S')}"
    try:
        sdk.create_git_branch(
            project_id=project_id, body=models40.WriteGitBranch(name=branch_name)
        )
    except Exception:  # noqa: BLE001
        try:
            sdk.update_git_branch(
                project_id=project_id, body=models40.WriteGitBranch(name=branch_name)
            )
        except Exception as e:  # noqa: BLE001
            logger.debug(f"Branch switch notice: {e}")

    targets = _resolve_matching_tables(
        sdk=sdk,
        connection=connection,
        dataset=dataset,
        schema=schema,
        table=table,
        match_pattern=match,
    )

    synced_views: list[str] = []
    errors: list[dict[str, str]] = []

    for ds, sch, tbl in targets:
        target_folder = (
            folder
            or (f"views/{ds}/{sch}" if ds and sch else f"views/{sch}" if sch else "views")
        ).strip("/")
        view_path = f"{target_folder}/{tbl}.view.lkml"

        existing_content: str | None = None
        try:
            existing_content = sdk.get_file_content(
                project_id=project_id, file_path=view_path
            )
        except Exception:  # noqa: BLE001
            existing_content = None

        if existing_content is not None:
            if not is_autogenerated_view(existing_content):
                err_msg = (
                    f"Refusing to overwrite {view_path}: missing # AUTOGENERATED "
                    "header comment at top of file."
                )
                logger.error(err_msg)
                errors.append({"view_file_path": view_path, "error": err_msg})
                _log_sync_artifact(
                    sdk,
                    {
                        "event_id": f"{now_iso}_{ds or ''}.{sch}.{tbl}".strip("_."),
                        "timestamp": now_iso,
                        "dataset": ds,
                        "schema": sch,
                        "table": tbl,
                        "event_type": event_type,
                        "looker_project_id": project_id,
                        "connection": connection,
                        "view_file_path": view_path,
                        "status": "error_missing_header",
                        "pr_url": None,
                        "error": err_msg,
                    },
                )
                continue
            try:
                sdk.delete_file(project_id=project_id, file_path=view_path)
            except Exception as e:  # noqa: BLE001
                logger.debug(f"Delete before regenerate notice for {view_path}: {e}")
        else:
            _ensure_remote_directory(
                sdk=sdk, project_id=project_id, file_path=view_path
            )

        sdk.generate_lookml_with_new_files(
            project_id=project_id,
            body={"tables": [{"schema": sch, "table_name": tbl, "base_view": True}]},
            connection=connection,
            model_name=resolved_model,
            folder_name=target_folder,
            file_type_for_explores="none",
            generate_descriptions=True,
            add_autogenerated_header=True,
        )
        synced_views.append(view_path)

    status = "up_to_date"
    pr_url: str | None = None
    if synced_views:
        commit_msg = f"chore(lookml): auto-upsert {len(synced_views)} view(s)"
        try:
            sdk.commit(
                project_id=project_id,
                body=ProjectCommitRequest(message=commit_msg).model_dump(
                    exclude_none=True
                ),
            )
        except Exception as e:  # noqa: BLE001
            logger.debug(f"Commit notice: {e}")

        if create_pr:
            pr_url = _open_github_pr(sdk, project_id, branch_name, commit_msg)
            status = "pr_opened" if pr_url else "committed"
        elif deploy:
            try:
                sdk.deploy_to_production(project_id=project_id)
                status = "deployed"
            except Exception as deploy_err:  # noqa: BLE001
                logger.debug(
                    f"Deploy failed ({deploy_err}), attempting GitHub PR fallback..."
                )
                pr_url = _open_github_pr(sdk, project_id, branch_name, commit_msg)
                status = "pr_opened" if pr_url else "error_deploy_failed"
        else:
            status = "committed"

        for view_path in synced_views:
            _log_sync_artifact(
                sdk,
                {
                    "event_id": f"{now_iso}_{view_path}",
                    "timestamp": now_iso,
                    "dataset": dataset,
                    "schema": schema,
                    "looker_project_id": project_id,
                    "connection": connection,
                    "view_file_path": view_path,
                    "branch": branch_name,
                    "status": status,
                    "pr_url": pr_url,
                    "error": None,
                },
            )
    elif errors:
        status = "error_missing_header"

    return {
        "status": status,
        "branch": branch_name,
        "synced_views": synced_views,
        "errors": errors,
        "pr_url": pr_url,
    }


@lookml_group.command(name="create")
def create_cmd(
    ctx: typer.Context,
    project_id: Annotated[
        str, typer.Option("--project-id", "--project", "-p", help="Looker project ID")
    ],
    connection: Annotated[
        str, typer.Option("--connection", "-c", help="Looker database connection name")
    ],
    model: Annotated[
        str | None,
        typer.Option("--model", help="LookML model name (defaults to project ID)"),
    ] = None,
    dataset: Annotated[
        str | None,
        typer.Option(
            "--dataset",
            "-d",
            help="Optional database/catalog name for views/{dataset}/{schema} folder path",
        ),
    ] = None,
    schema: Annotated[
        str | None, typer.Option("--schema", "-s", help="Database schema name")
    ] = None,
    table: Annotated[
        str | None,
        typer.Option(
            "--table", "-t", help="Table name to create or update LookML view for"
        ),
    ] = None,
    match: Annotated[
        str | None,
        typer.Option(
            "--match",
            "-m",
            help="Wildcard pattern to match schemas and tables (e.g. 'raw.*', '*.orders*')",
        ),
    ] = None,
    folder: Annotated[
        str | None,
        typer.Option(
            "--folder", help="Target folder in Looker project for generated views"
        ),
    ] = None,
    branch_prefix: Annotated[
        str,
        typer.Option(
            "--branch-prefix", help="Branch prefix for Looker dev branch and PRs"
        ),
    ] = "lkr-sync/",
    deploy: Annotated[
        bool,
        typer.Option(
            "--deploy/--no-deploy",
            help="Deploy changes to production, falling back to a GitHub PR if required",
        ),
    ] = True,
    create_pr: Annotated[
        bool,
        typer.Option(
            "--create-pr",
            help="Open a GitHub PR instead of deploying directly to production",
        ),
    ] = False,
    event_json: Annotated[
        str | None,
        typer.Option(
            "--event-json", help="Cloud Logging or webhook event JSON payload"
        ),
    ] = None,
    port: Annotated[
        int | None,
        typer.Option(
            "--port", help="Run as an HTTP webhook listener on the specified port"
        ),
    ] = None,
):
    """
    Create or update LookML views from database tables using Looker's generation API.
    """
    sdk: ExtendedLooker40SDK = get_auth(ctx).get_current_sdk()
    common_kwargs: dict[str, Any] = {
        "sdk": sdk,
        "project_id": project_id,
        "connection": connection,
        "model_name": model,
        "dataset": dataset,
        "schema": schema,
        "table": table,
        "match": match,
        "folder": folder,
        "branch_prefix": branch_prefix,
        "deploy": deploy,
        "create_pr": create_pr,
    }

    if port is not None:
        import uvicorn
        from fastapi import FastAPI, Request

        api = FastAPI()

        @api.post("/webhook")
        async def webhook(request: Request):
            raw = (await request.body()).decode("utf-8")
            return create_lookml_views(**common_kwargs, event_json=raw)

        uvicorn.run(api, host="0.0.0.0", port=port)
        return

    res = create_lookml_views(**common_kwargs, event_json=event_json)
    if res["synced_views"]:
        typer.echo(
            f"Successfully created/updated {len(res['synced_views'])} view(s) [{res['status']}]:"
        )
        for v in res["synced_views"]:
            typer.echo(f"  - {v}")
        if res["pr_url"]:
            typer.echo(f"PR opened: {res['pr_url']}")
    if res["errors"]:
        for err in res["errors"]:
            typer.echo(f"Error: {err['error']}", err=True)
        if not res["synced_views"]:
            raise typer.Exit(1)
    if not res["synced_views"] and not res["errors"]:
        typer.echo("No matching tables found to synchronize.")



